# Replay only the MathML payload generated by the tested browser Copy MathML action.
# This is NOT a direct browser-to-Word clipboard pass: the broker boundary is explicit.
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Windows.Forms
$probeRoot = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$probeDir = Join-Path $probeRoot 'Project Files/Question Samples/clipboard-captures'
$sourceFile = Join-Path $probeDir 'browser-outbound-mathml.mml'
$mathML = [IO.File]::ReadAllText($sourceFile)
if ($mathML.Length -gt 20000 -or $mathML -notmatch '<mfrac>' -or $mathML -notmatch '<msqrt>') { throw 'Expected the reviewed fraction/root fixture only.' }
$fragmentStart = '<html><body><!--StartFragment-->'
$fragmentEnd = '<!--EndFragment--></body></html>'
$headerTemplate = "Version:0.9`r`nStartHTML:{0:D10}`r`nEndHTML:{1:D10}`r`nStartFragment:{2:D10}`r`nEndFragment:{3:D10}`r`n"
$startHTML = [Text.Encoding]::UTF8.GetByteCount(($headerTemplate -f 0,0,0,0))
$startFragment = $startHTML + [Text.Encoding]::UTF8.GetByteCount($fragmentStart)
$endFragment = $startFragment + [Text.Encoding]::UTF8.GetByteCount($mathML)
$endHTML = $endFragment + [Text.Encoding]::UTF8.GetByteCount($fragmentEnd)
$cfHTML = ($headerTemplate -f $startHTML,$endHTML,$startFragment,$endFragment) + $fragmentStart + $mathML + $fragmentEnd
$wordProbe = $null
$testDocument = $null
$results = @()
$saveNone = 0
$priorUpdateLinks = $null
try {
    $wordProbe = New-Object -ComObject Word.Application
    $wordProbe.Visible = $false
    $wordProbe.DisplayAlerts = 0
    $wordProbe.AutomationSecurity = 3
    $priorUpdateLinks = $wordProbe.Options.UpdateLinksAtOpen
    $wordProbe.Options.UpdateLinksAtOpen = $false
    foreach ($routeName in @('browser_html_and_plain_payload_replay','plain_mathml_replay')) {
        $testDocument = $wordProbe.Documents.Add()
        try {
            $data = New-Object System.Windows.Forms.DataObject
            $data.SetData('UnicodeText',$false,[string]$mathML)
            if ($routeName -eq 'browser_html_and_plain_payload_replay') { $data.SetData('HTML Format',$false,[string]$cfHTML) }
            [System.Windows.Forms.Clipboard]::SetDataObject($data,$true,6,200)
            Start-Sleep -Milliseconds 250
            $testDocument.Content.Paste()
            $nativeXML = $testDocument.Content.WordOpenXML
            [IO.File]::WriteAllText((Join-Path $probeDir "$routeName.xml"),$nativeXML,[Text.UTF8Encoding]::new($false))
            [xml]$native = $nativeXML
            $ns = New-Object System.Xml.XmlNamespaceManager($native.NameTable)
            $ns.AddNamespace('m','http://schemas.openxmlformats.org/officeDocument/2006/math')
            $fractions = $native.SelectNodes('//m:f',$ns).Count
            $roots = $native.SelectNodes('//m:rad',$ns).Count
            $num = ($native.SelectNodes('//m:f/m:num//m:t',$ns) | ForEach-Object { $_.InnerText }) -join ''
            $den = ($native.SelectNodes('//m:f/m:den//m:t',$ns) | ForEach-Object { $_.InnerText }) -join ''
            $rad = ($native.SelectNodes('//m:rad/m:e//m:t',$ns) | ForEach-Object { $_.InnerText }) -join ''
            $results += @{ route=$routeName; native_equations=$testDocument.OMaths.Count; fractions=$fractions; roots=$roots;
                numerator_is_2=($num -eq '2'); denominator_is_3=($den -eq '3'); radicand_is_5=($rad -eq '5');
                result=$(if($testDocument.OMaths.Count -eq 1 -and $fractions -eq 1 -and $roots -eq 1 -and $num -eq '2' -and $den -eq '3' -and $rad -eq '5'){'native_structure_verified_for_replayed_fixture'}else{'not_verified'});
                visual_fidelity='not_verified'; temporary_document='in memory only, closed without saving'; }
        } catch { $results += @{ route=$routeName; result='environment_or_paste_failure'; diagnostic=$_.Exception.Message } }
        finally { if ($testDocument) { $testDocument.Close([ref]$saveNone); $testDocument=$null } }
    }
    $report = @{ date='2026-10-16'; word_file_version=(Get-Item (Join-Path $wordProbe.Path 'WINWORD.EXE')).VersionInfo.FileVersion;
        source='Known synthetic 2/3 + sqrt(5), produced by the actual browser Copy MathML action';
        source_sha256=(Get-FileHash -LiteralPath $sourceFile -Algorithm SHA256).Hash.ToLower();
        method='Controlled Windows clipboard payload replay into native Word; distinct from direct browser clipboard interoperability';
        routes=$results; paid_dependency_added=$false; native_browser_to_word_clipboard_verified=$false; }
    $report | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $probeRoot 'docs/reference/WORD-OUTBOUND-PROBE.json') -Encoding utf8
    Write-Output ($results | ConvertTo-Json -Depth 5)
} finally {
    if ($testDocument) { try { $testDocument.Close([ref]$saveNone) } catch {} }
    if ($wordProbe) { if ($null -ne $priorUpdateLinks) { $wordProbe.Options.UpdateLinksAtOpen = $priorUpdateLinks }; try { $wordProbe.Quit([ref]$saveNone) } catch {}; [void][Runtime.InteropServices.Marshal]::ReleaseComObject($wordProbe) }
}
